import '../../styles/leave.css';




const buildManagerHistory = (data) => {
  return (data || []).flatMap(item => {
    const base = {
      ...item
    };

    // // Cancel Requested
    // if (item.status === "CANCEL_REQUESTED") {
    //   return [
    //     {
    //       ...base,
    //       requestType: "LEAVE",
    //       displayStatus: "Cancelled",
    //       uniqueId: `${item.id}-leave`
    //     },

    //     {
    //       ...base,
    //       requestType: "CANCEL",
    //       displayStatus: "Applied",
    //       uniqueId: `${item.id}-cancel`
    //     }
    //   ];
    // }

    if (item.status === "CANCEL_REQUESTED") {
  return [
    {
      ...base,
      requestType: "CANCEL",
      displayStatus: "Applied",
      uniqueId: `${item.id}-cancel`
    },

    {
      ...base,
      requestType: "LEAVE",
      displayStatus: "Cancelled",
      uniqueId: `${item.id}-leave`
    }
  ];
}
    // Cancelled
    // if (item.status === "CANCELLED") {
    //   return [
    //     {
    //       ...base,
    //       requestType: "CANCEL",
    //       displayStatus: "Approved",
    //       uniqueId: `${item.id}-cancelled`
    //     }
    //   ];
    // }

    if (item.status === "CANCELLED") {
  return [
    {
      ...base,
      requestType: "CANCEL",
      displayStatus: "Approved",
      uniqueId: `${item.id}-cancel`
    },
    {
      ...base,
      requestType: "LEAVE",
      displayStatus: "Cancelled",
      uniqueId: `${item.id}-leave`
    }
  ];
}

    // Approved
    if (item.status === "APPROVED") {
      return [
        {
          ...base,
          requestType: "LEAVE",
          displayStatus: "Approved",
          uniqueId: `${item.id}-approved`
        }
      ];
    }

    // Rejected
    if (item.status === "REJECTED") {
      return [
        {
          ...base,
          requestType: "LEAVE",
          displayStatus: "Rejected",
          uniqueId: `${item.id}-rejected`
        }
      ];
    }

    // Applied / Pending
    return [
      {
        ...base,
        requestType: "LEAVE",
        displayStatus: "Applied",
        uniqueId: `${item.id}-pending`
      }
    ];
  });
};
function MyTeamLeave() {
  const [leaves, setLeaves] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [statusFilter, setStatusFilter] = useState('');
  const [search, setSearch] = useState('');
  const [isManager, setIsManager] = useState(false);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [remarksMap, setRemarksMap] = useState({});



  const [searchInput, setSearchInput] = useState('');

  const [order, setOrder] = useState('desc');
  const [orderBy, setOrderBy] = useState('');


  const [managerId, setManagerId] = useState(null);

  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success',
    action: null
  });

  useEffect(() => {
    const username = localStorage.getItem('username');
    if (!username) {
      setLoading(false);
      return;
    }

    //Data Fetching Logic....
    const fetchData = async () => {
      try {
        const userResponse = await API.get(`/users/username/${username}`);
        const user = userResponse.data;


        console.log("User:", user);
        console.log("Role:", user.role);


        if (!user) {
          setLoading(false);
          return;
        }

        // if (user.role && user.role.trim().toUpperCase() === 'MANAGER') {
        //   setIsManager(true);
        if (user.role && user.role.trim().toUpperCase() === 'MANAGER') {
  setIsManager(true);
  setManagerId(user.id);
          // const leaveResponse = await API.get(`/leave/team/${user.id}`);
          const leaveResponse = await API.get('/leave/team', {
            headers: {
              managerId: user.id
            }
          });


          // setLeaves(leaveResponse.data || []);
          // setFiltered(leaveResponse.data || []);
          const formattedData = buildManagerHistory(
            leaveResponse.data || []
          );

          setLeaves(formattedData);
          setFiltered(formattedData);
        } else {
          setLeaves([]);
          setFiltered([]);
          setIsManager(false);
        }
      } catch (error) {
        console.error('Error loading team leaves', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // useEffect(() => {
  //   let data = [...leaves];

  //   //Filtering Logic....
  //   if (statusFilter) {
  //     if (statusFilter === 'PENDING') {
  //       data = data.filter((leave) => normalizeStatus(leave) === 'Applied');
  //     } else {
  //       data = data.filter((leave) => leave.status === statusFilter);
  //     }
  //   }



  //   if (search.trim().length >= 3) {
  //     const q = search.toLowerCase();
  //     data = data.filter(
  //       (leave) =>
  //         String(leave.userId ?? '').toLowerCase().includes(q) ||
  //         leave.username?.toLowerCase().includes(q) ||
  //         leave.leaveType?.toLowerCase().includes(q) ||
  //         leave.reason?.toLowerCase().includes(q)
  //     );
  //   }

  //   // setFiltered(data);
  //   setFiltered(
  //     data.sort((a, b) => {
  //       const dateA = a.appliedOn ? new Date(a.appliedOn).getTime() : 0;
  //       const dateB = b.appliedOn ? new Date(b.appliedOn).getTime() : 0;
  //       return dateB - dateA;
  //     })
  //   );

  //   setCurrentPage(1);
  // }, [statusFilter, search, leaves]);




  useEffect(() => {
    let data = [...leaves];

    // Status Filter
    if (statusFilter) {
      // if (statusFilter === 'PENDING') {
      //   data = data.filter(
      //     (leave) => normalizeStatus(leave) === 'Applied'
      //   );
      // } else {
      //   data = data.filter(
      //     (leave) => leave.status === statusFilter
      //   );
      // }

      if (statusFilter === 'PENDING') {
  data = data.filter(
    leave => leave.displayStatus === 'Applied'
  );
}
else if (statusFilter === 'APPROVED') {
  data = data.filter(
    leave => leave.displayStatus === 'Approved'
  );
}
else if (statusFilter === 'REJECTED') {
  data = data.filter(
    leave => leave.displayStatus === 'Rejected'
  );
}
else if (statusFilter === 'CANCELLED') {
  data = data.filter(
    leave => leave.displayStatus === 'Cancelled'
  );
}
    }

    // Search Filter
    if (search.trim().length >= 3) {
      const q = search.toLowerCase();

      data = data.filter(
        (leave) =>
          String(leave.userId ?? '').toLowerCase().includes(q) ||
          leave.username?.toLowerCase().includes(q) ||
          leave.leaveType?.toLowerCase().includes(q) ||
          leave.reason?.toLowerCase().includes(q)
      );
    }

    // Default sort only when no column sort selected
    // if (!orderBy) {
    //   data.sort((a, b) => {
    //     const dateA = a.appliedOn
    //       ? new Date(a.appliedOn).getTime()
    //       : 0;

    //     const dateB = b.appliedOn
    //       ? new Date(b.appliedOn).getTime()
    //       : 0;

    //     return dateB - dateA;
    //   });
    // }

    if (!orderBy) {
  data.sort((a, b) => {

    const dateA = a.appliedOn
      ? new Date(a.appliedOn).getTime()
      : 0;

    const dateB = b.appliedOn
      ? new Date(b.appliedOn).getTime()
      : 0;

    if (dateA !== dateB) {
      return dateB - dateA;
    }

    if (
      a.requestType === "CANCEL" &&
      b.requestType === "LEAVE"
    ) {
      return -1;
    }

    if (
      a.requestType === "LEAVE" &&
      b.requestType === "CANCEL"
    ) {
      return 1;
    }

    return 0;
  });
}

    setFiltered(data);
    setCurrentPage(1);

  }, [statusFilter, search, leaves, orderBy, order]);

  useEffect(() => {
    const newTotalPages = Math.max(1, Math.ceil(filtered.length / pageSize));

    if (currentPage > newTotalPages) {
      setCurrentPage(1);
    }
  }, [filtered, pageSize, currentPage]);


  const handleCancelDecision = async (id, action) => {
    const remarks = remarksMap[id];

    if (!remarks) {
      showSnackbar("Please enter remarks", "error");
      return;
    }

    showSnackbar(
      "Are you sure?",
      "warning",
      <>
        <Button
          color="inherit"
          size="small"
          onClick={async () => {
            handleSnackbarClose();

            try {
              await API.put(`/leave/cancel-decision/${id}/${action}`, { remarks });

   
const refreshed = await API.get('/leave/team', {
  headers: {
    managerId: managerId
  }
});



const formattedData = buildManagerHistory(
  refreshed.data || []
);

setLeaves(formattedData);
setFiltered(formattedData);
              showSnackbar(
                action === 'APPROVE'
                  ? "Leave cancellation approved"
                  : "Leave cancellation rejected",
                "success"
              );

           
            } catch (error) {

  console.error(
    "Cancel Decision Error",
    error.response?.data || error
  );

  showSnackbar(
    error?.response?.data?.message ||
    "Failed to process cancel",
    "error"
  );
}
          }}
        >
          YES
        </Button>

        <Button color="inherit" size="small" onClick={handleSnackbarClose}>
          NO
        </Button>
      </>
    );
  };



  const handleApprove = async (id) => {
    const remarks = remarksMap[id];

    if (!remarks) {
      showSnackbar("Please enter remarks before approving", "error");
      return;
    }

    showSnackbar(
      "Approve this leave?",
      "warning",
      <>
        <Button
          color="inherit"
          size="small"
          onClick={async () => {
            handleSnackbarClose();

            try {
              await API.put(`/leave/approve/${id}`, { remarks });

        
              setLeaves(prev =>
  prev.map(l =>
    l.id === id
      ? {
          ...l,
          status: 'APPROVED',
          displayStatus: 'Approved',
          approverRemarks: remarks
        }
      : l
  )
);

              showSnackbar("Leave approved successfully", "success");

            } catch {
              showSnackbar("Failed to approve leave", "error");
            }
          }}
        >
          YES
        </Button>

        <Button color="inherit" size="small" onClick={handleSnackbarClose}>
          NO
        </Button>
      </>
    );
  };


  const handleReject = async (id) => {
    const remarks = remarksMap[id];

    if (!remarks) {
      showSnackbar("Please enter rejection reason", "error");
      return;
    }

    showSnackbar(
      "Reject this leave?",
      "warning",
      <>
        <Button
          color="inherit"
          size="small"
          onClick={async () => {
            handleSnackbarClose();

            try {
              await API.put(`/leave/reject/${id}`, { remarks });

           
              setLeaves(prev =>
  prev.map(l =>
    l.id === id
      ? {
          ...l,
          status: 'REJECTED',
          displayStatus: 'Rejected',
          approverRemarks: remarks
        }
      : l
  )
);

              // showSnackbar("Leave rejected successfully", "success");
              showSnackbar("Leave rejected successfully", "error");


            } catch {
              showSnackbar("Failed to reject leave", "error");
            }
          }}
        >
          YES
        </Button>

        <Button color="inherit" size="small" onClick={handleSnackbarClose}>
          NO
        </Button>
      </>
    );
  };
  const formatDate = (value) => {
    if (!value) return '-';

    const date = new Date(value);

    const day = String(date.getDate()).padStart(2, '0');

    const month = date.toLocaleString('en-US', {
      month: 'short'
    });

    const year = String(date.getFullYear()).slice(-4);

    return `${day}-${month}-${year}`;
  };

  const normalizeStatus = (item) => {
    const status = item?.status;

    if (!status || status === 'PENDING') {
      return 'Applied';
    }

    if (status === 'CANCEL_REQUESTED') {
      return 'CANCEL_REQUESTED';
    }

    return status;
  };


  const formatStatus = (status) => {
    if (!status) return '';

    if (status === 'Applied') return 'Applied';
    if (status === 'CANCEL_REQUESTED') return 'Cancel Requested';

    return status
      .toLowerCase()
      .replace(/_/g, ' ')
      .replace(/\b\w/g, char => char.toUpperCase());
  };


  const getRequestType = (item) => {
    return item.requestType === 'CANCEL'
      ? 'Cancel Application'
      : 'Leave Application';
  };

  const [expandedRows, setExpandedRows] = useState({});
  const toggleReason = (id) => {
    setExpandedRows(prev => ({
      ...prev,
      [id]: !prev[id]
    }));
  };

  const handleDownloadExcel = () => {
    if (!filtered || filtered.length === 0) {
      showSnackbar("No data to export", "error");
      return;
    }

    const excelData = paginatedData.map(item => ({
      "Employee No": item.userId || "-",
      "Employee Name": formatName(item.username) || "-",
      "Applied On": formatDate(item.appliedOn),
      "Leave Type": item.leaveType || "-",
      "From Date": formatDate(item.fromDate),
      "To Date": formatDate(item.toDate),
      "No. of Days": item.days || 0,
      "Status": formatStatus(normalizeStatus(item)),
      "Request Type": getRequestType(item),
      "Contact Number": item.phone || "-",
      "Reason": item.reason || "-",
      "Approver Remarks": item.approverRemarks || "-"
    }));


    /// Excel Export Logic...
    const worksheet = XLSX.utils.json_to_sheet(excelData);


    const colWidths = Object.keys(excelData[0]).map(key => ({
      wch: key.length + 5
    }));
    worksheet["!cols"] = colWidths;

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Team Leave");

    // XLSX.writeFile(workbook, "MyTeamLeave.xlsx");
    const randomNumber = Math.floor(100000 + Math.random() * 900000);
    XLSX.writeFile(workbook, `Leave_${randomNumber}.xlsx`);
  };


  const showSnackbar = (message, severity = 'success', action = null) => {
    setSnackbar({
      open: true,
      message,
      severity,
      action
    });
  };

  const handleSnackbarClose = () => {
    setSnackbar(prev => ({ ...prev, open: false }));
  };


  const handleRequestSort = (property) => {
    const isAsc = orderBy === property && order === 'asc';
    const newOrder = isAsc ? 'desc' : 'asc';

    setOrder(newOrder);
    setOrderBy(property);

    const sortedData = [...filtered].sort((a, b) => {
      let valA;
      let valB;

      switch (property) {
        case 'userId':
          valA = Number(a.userId || 0);
          valB = Number(b.userId || 0);
          break;

        case 'employee':
          valA = (formatName(a.username) || '').toLowerCase();
          valB = (formatName(b.username) || '').toLowerCase();
          break;

        case 'appliedOn':
          valA = a.appliedOn ? new Date(a.appliedOn).getTime() : 0;
          valB = b.appliedOn ? new Date(b.appliedOn).getTime() : 0;
          break;

        case 'leaveType':
          valA = (a.leaveType || '').toLowerCase();
          valB = (b.leaveType || '').toLowerCase();
          break;

        case 'fromDate':
          valA = a.fromDate ? new Date(a.fromDate).getTime() : 0;
          valB = b.fromDate ? new Date(b.fromDate).getTime() : 0;
          break;

        case 'toDate':
          valA = a.toDate ? new Date(a.toDate).getTime() : 0;
          valB = b.toDate ? new Date(b.toDate).getTime() : 0;
          break;

        case 'days':
          valA = Number(a.days || 0);
          valB = Number(b.days || 0);
          break;

        case 'status':
          valA = formatStatus(normalizeStatus(a)).toLowerCase();
          valB = formatStatus(normalizeStatus(b)).toLowerCase();
          break;

        case 'requestType':
          valA = (getRequestType(a) || '').toLowerCase();
          valB = (getRequestType(b) || '').toLowerCase();
          break;

        case 'phone':
          valA = Number(a.phone || 0);
          valB = Number(b.phone || 0);
          break;

        case 'reason':
          valA = (a.reason || '').toLowerCase();
          valB = (b.reason || '').toLowerCase();
          break;

        case 'approverRemarks':
          valA = (a.approverRemarks || '').toLowerCase();
          valB = (b.approverRemarks || '').toLowerCase();
          break;

        default:
          return 0;
      }

      if (valA < valB) return newOrder === 'asc' ? -1 : 1;
      if (valA > valB) return newOrder === 'asc' ? 1 : -1;

      return 0;
    });

    setFiltered(sortedData);
  };

  //Pagination Logic...
  const totalPages = Math.ceil(filtered.length / pageSize) || 1;

  const paginatedData = filtered.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );



  console.log("Total rows:", filtered.length);
  console.log("Page size:", pageSize);
  console.log("Total pages:", totalPages);



  console.log("Leaves:", leaves);
  console.log("Filtered:", filtered);
  console.log("Paginated Data:", paginatedData);




  const getApproverRemarks = (item) => {

  if (
    item.displayStatus === "Applied"
  ) {
    return "";
  }

  if (
    item.requestType === "LEAVE" &&
    item.displayStatus === "Cancelled"
  ) {
    return "";
  }

  return item.approverRemarks || "-";
};

  return (
    <Layout>
      <div className="container-fluid projectAccounting leave-page">
        <div className="leave-card">

          <div className="page-header">
            <h2>My Team Leave</h2>
            <button
              type="button"
              className="back-btn"
              onClick={() => window.history.back()}
            >
              <i className="bi bi-chevron-double-left"></i> Back
            </button>
          </div>


          <div className="tableListViewHeader myteam-toolbar">

            {/* LEFT */}
            <div className="toolbar-left">
              {/* <button className="paginator-btn">
                <i className="bi bi-chevron-left"></i>
              </button> */}
              <button
                className="paginator-btn"
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
              >


                <i className="bi bi-chevron-left"></i>
              </button>


              <select
                className="form-select page-size-dropdown"
                value={pageSize}
                // onChange={(e) => setPageSize(Number(e.target.value))}
                onChange={(e) => {
                  setPageSize(Number(e.target.value));
                  setCurrentPage(1);
                }}
              >
                <option value={10}>10</option>
                <option value={25}>25</option>
                <option value={50}>50</option>
                <option value={100}>100</option>
              </select>

              {/* <button className="paginator-btn">
                <i className="bi bi-chevron-right"></i>
              </button> */}
              <button
                className="paginator-btn"
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
              >

                <i className="bi bi-chevron-right"></i>
              </button>

              {/* ✅ PAGE TEXT IS NEXT TO DROPDOWN */}

              <span className="page-indicator-box">
                Current Page: {currentPage}
              </span>

            </div>

            {/* RIGHT */}
            <div className="toolbar-right">
              <select
                className="form-select status-select"
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
              >
                {/* <option value="">Select Status</option> */}

                <option value="" disabled hidden>
                  Select Status
                </option>

                <option value="PENDING">Applied</option>
                <option value="APPROVED">Approved</option>
                <option value="REJECTED">Rejected</option>
                <option value="CANCELLED">Cancelled</option>
              </select>


              <input
                type="text"
                className="form-control search-input"
                placeholder="Type min 3 characters"
                value={searchInput}
                onChange={(e) => {
                  const value = e.target.value;
                  setSearchInput(value);

                  if (value.trim().length < 3) {
                    setSearch('');
                  }
                }}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();

                    if (searchInput.trim().length >= 3) {
                      setSearch(searchInput.trim());
                    }
                  }
                }}
              />

              <button
                type="button"
                className="toolbar-icon-btn"
                onClick={() => {
                  if (searchInput.trim().length >= 3) {
                    setSearch(searchInput.trim());
                  }
                }}
              >
                <i className="bi bi-search"></i>
              </button>
              {/* <button
                className="toolbar-icon-btn file-download-btn"
                onClick={handleDownloadPDF}
                title="Download PDF"
              >
                <i className="bi bi-file-earmark-x"></i>
              </button> */}

              <button
                className="toolbar-icon-btn file-download-btn"
                onClick={handleDownloadExcel}
                title="Download Excel"
              >
                <i className="bi bi-file-earmark-excel"></i>
              </button>

            </div>

          </div>

          <div className="table-responsive" id="leave-table">
            <table className="table custom-table bizx-table myteam-table">
              {/* <thead>
                <tr>
                  <th>Employee No.</th>
                  <th>Employee Name</th>
                  <th>Applied On</th>
                  <th>Leave Type</th>
                  <th>From Date</th>
                  <th>To Date</th>
                  <th>No. of Days</th>
                  <th>Status</th>
                  <th>Request Type</th>
                  <th>Contact Number</th>
                  <th>Reason</th>
                  <th>Approver Remarks</th>
                  <th>Action</th>
                </tr>
              </thead> */}

              <thead>
                <tr>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'userId'}
                      direction={orderBy === 'userId' ? order : 'asc'}
                      onClick={() => handleRequestSort('userId')}
                    >
                      Employee No.
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'employee'}
                      direction={orderBy === 'employee' ? order : 'asc'}
                      onClick={() => handleRequestSort('employee')}
                    >
                      Employee Name
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'appliedOn'}
                      direction={orderBy === 'appliedOn' ? order : 'asc'}
                      onClick={() => handleRequestSort('appliedOn')}
                    >
                      Applied On
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'leaveType'}
                      direction={orderBy === 'leaveType' ? order : 'asc'}
                      onClick={() => handleRequestSort('leaveType')}
                    >
                      Leave Type
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'fromDate'}
                      direction={orderBy === 'fromDate' ? order : 'asc'}
                      onClick={() => handleRequestSort('fromDate')}
                    >
                      From Date
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'toDate'}
                      direction={orderBy === 'toDate' ? order : 'asc'}
                      onClick={() => handleRequestSort('toDate')}
                    >
                      To Date
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'days'}
                      direction={orderBy === 'days' ? order : 'asc'}
                      onClick={() => handleRequestSort('days')}
                    >
                      No. of Days
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'status'}
                      direction={orderBy === 'status' ? order : 'asc'}
                      onClick={() => handleRequestSort('status')}
                    >
                      Status
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'requestType'}
                      direction={orderBy === 'requestType' ? order : 'asc'}
                      onClick={() => handleRequestSort('requestType')}
                    >
                      Request Type
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'phone'}
                      direction={orderBy === 'phone' ? order : 'asc'}
                      onClick={() => handleRequestSort('phone')}
                    >
                      Contact Number
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'reason'}
                      direction={orderBy === 'reason' ? order : 'asc'}
                      onClick={() => handleRequestSort('reason')}
                    >
                      Reason
                    </TableSortLabel>
                  </th>

                  <th>
                    <TableSortLabel
                      active={orderBy === 'approverRemarks'}
                      direction={orderBy === 'approverRemarks' ? order : 'asc'}
                      onClick={() => handleRequestSort('approverRemarks')}
                    >
                      Approver Remarks
                    </TableSortLabel>
                  </th>

                  <th>Action</th>

                </tr>
              </thead>



              <tbody>
                {loading ? (
                  <tr>
                    <td colSpan="13" className="text-center">Loading</td>
                  </tr>
                ) : filtered.length === 0 ? (
                  <tr>
                    <td colSpan="13" className="no-data">No Data Found</td>
                  </tr>
                ) : (
                  // paginatedData.map((item) => {

                  //   console.log(item);

                  //   return (

                  paginatedData.map((item) => {

  console.log(item);

  const isActionable =
    item.displayStatus === "Applied";

  return (
                      // <tr key={item.id}>
                      <tr key={item.uniqueId}>
                        <td>{item.userId || '-'}</td>

                        <td>{formatName(item.username) || '-'}</td>

                        <td>{formatDate(item.appliedOn)}</td>

                        <td>{item.leaveType}</td>

                        <td>{formatDate(item.fromDate)}</td>

                        <td>{formatDate(item.toDate)}</td>

                        <td>{item.days}</td>

                        {/* <td>
                          <span className={getStatusClass(item.status)}>
                            {normalizeStatus(item.status)}
                          </span>
                        </td> */}

                        <td>
                          <span
                            className={
                              item.displayStatus === "Approved"
                                ? "status-approved"
                                : item.displayStatus === "Rejected"
                                  ? "status-rejected"
                                  : item.displayStatus === "Cancelled"
                                    ? "status-cancelled"
                                    : "status-pending"
                            }
                          >
                            {item.displayStatus}
                          </span>
                        </td>
                        {/* <td>
                          <span className={getStatusClass(item.status)}>
                            {formatStatus(normalizeStatus(item))}
                          </span>
                        </td> */}

                        <td>{getRequestType(item)}</td>
                        <td>{item.phone || '-'}</td>


                        <td>
                          {item.reason ? (
                            <>
                              {expandedRows[item.id]
                                ? item.reason
                                : item.reason.length > 50
                                  ? item.reason.substring(0, 50) + '...'
                                  : item.reason
                              }

                              {item.reason.length > 50 && (
                                <span
                                  className="ms-2 toggle-icon-circle"
                                  onClick={() => toggleReason(item.id)}
                                >
                                  {expandedRows[item.id] ? (
                                    <i className="bi bi-chevron-up"></i>
                                  ) : (
                                    <i className="bi bi-chevron-down"></i>
                                  )}
                                </span>
                              )}
                            </>
                          ) : '-'}
                        </td>



<td className="approver-remarks">

  {(item.requestType === "CANCEL" &&
    item.displayStatus === "Applied") ||

   (item.requestType === "LEAVE" &&
    item.displayStatus === "Applied") ? (

    <input
      type="text"
      className="form-control"
      placeholder="Remarks"
      value={remarksMap[item.id] || ''}
      onChange={(e) =>
        setRemarksMap(prev => ({
          ...prev,
          [item.id]: e.target.value
        }))
      }
    />

  ) : (

    <div className="remarks-text">
      {getApproverRemarks(item)}
    </div>

  )}

</td>



<td>
  {isManager && (
    <div className="action-icons">

      {/* <button
        className={`icon-btn ${
          item.requestType === "LEAVE" &&
          item.displayStatus === "Cancelled"
            ? "disabled-btn"
            : ""
        }`}
        disabled={
          item.requestType === "LEAVE" &&
          item.displayStatus === "Cancelled"
        } */}
        <button
  className={`icon-btn ${
    !isActionable ? "disabled-btn" : ""
  }`}
  disabled={!isActionable}
        onClick={() => {
          if (item.requestType === "CANCEL") {
            handleCancelDecision(item.id, "APPROVE");
          } else {
            handleApprove(item.id);
          }
        }}
      >
        <i className="bi bi-check"></i>
      </button>

      {/* <button
        className={`icon-btn ${
          item.requestType === "LEAVE" &&
          item.displayStatus === "Cancelled"
            ? "disabled-btn"
            : ""
        }`}
        disabled={
          item.requestType === "LEAVE" &&
          item.displayStatus === "Cancelled"
        } */}

        <button
  className={`icon-btn ${
    !isActionable ? "disabled-btn" : ""
  }`}
  disabled={!isActionable}
        onClick={() => {
          if (item.requestType === "CANCEL") {
            handleCancelDecision(item.id, "REJECT");
          } else {
            handleReject(item.id);
          }
        }}
      >
        <i className="bi bi-x"></i>
      </button>

    </div>
  )}
</td>
                      </tr>

                    );
                  })
                )}
              </tbody>
            </table>
          </div>

        </div>
      </div>
      <Snackbar
        open={snackbar.open}
        autoHideDuration={snackbar.action ? null : 10000}
        onClose={(event, reason) => {
          if (reason === 'clickaway') return;
          handleSnackbarClose();
        }}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert severity={snackbar.severity} onClose={handleSnackbarClose}>
          {snackbar.message}
          {snackbar.action}
        </Alert>
      </Snackbar>

    </Layout>
  );
}

export default MyTeamLeave;
